package org.apache.commons.lang3.time;

import java.io.*;
import java.math.*;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class DateUtils_isSameDay_TriageGen0Test {

    @Test
    public void testIsSameDay_SameDaySameTime() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 0, 0);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 15, 30, 0);
        Assert.assertTrue("Should return true for the same day even if times differ", 
                DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_SameDaySameTimeExact() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 0, 0);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 0, 0);
        Assert.assertTrue("Should return true for identical calendars", 
                DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_DifferentDay() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 2);
        Assert.assertFalse("Should return false for different days", 
                DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_DifferentMonth() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.FEBRUARY, 1);
        Assert.assertFalse("Should return false for different months", 
                DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_DifferentYear() {
        Calendar cal1 = new GregorianCalendar(2022, Calendar.JANUARY, 1);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1);
        Assert.assertFalse("Should return false for different years", 
                DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_DifferentEra() {
        // Testing the ERA branch
        // Using a very large year to potentially trigger a different ERA if possible, 
        // but standard Gregorian is usually Era 1.
        Calendar cal1 = new GregorianCalendar(1, Calendar.JANUARY, 1); // Year 1 AD
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1);
        Assert.assertFalse("Should return false for different eras", 
                DateUtils.isSameDay(cal1, cal2));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsSameDay_NullFirstArgument() {
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1);
        DateUtils.isSameDay(null, cal2);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsSameDay_NullSecondArgument() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1);
        DateUtils.isSameDay(cal1, null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsSameDay_BothArgumentsNull() {
        DateUtils.isSameDay(null, null);
    }
}
